// Moria: entry point for moria.html. Fan work — Tolkien's world belongs to the Tolkien Estate, nothing from any
// book, film or game is used, and every shape is this project's own. The mountains are generated by
// tools/make-moria.py; the gates and the halls under the mountain are modelled here; the engine is the one Chicago
// and New York share.
import {report,LOAD,configureLoading,installErrorHandlers} from '../core/diag.js';
import {boot} from '../core/shell.js';
import {build} from '../engine/build.js';
import {landmarks} from './landmarks.js';
import {halls} from './halls.js';
import {city} from './city.js';
import {realm} from './realm.js';
import {deep} from './deep.js';
import {walk} from './walk.js';
import {events} from './events.js';
installErrorHandlers();window.LOAD=LOAD;
configureLoading({
  lines:[
    'Fan work. Tolkien\'s world belongs to the Tolkien Estate; every shape here is this project\'s own geometry.',
    'The Doors of Durin are seen only under starlight and moonlight. Speak, friend, and enter.',
    'Behold the great realm and dwarf-city of the Dwarrowdelf.',
    'A slender bridge of stone, without kerb or rail, that spans the chasm in one curving spring.',
    'Press See inside to make the mountain glass, and see the halls where they lie in it.',
    'Press Moria to see Khazad-dûm in Durin\'s day, with the lamps lit.',
    'Press Walk to go about the halls at a Dwarf\'s eye height, and Map to see the whole city.',
    'Drums, drums in the deep.',
  ],
  prefix:'delving Khazad-dûm… ',labels:{'map-data':'reading the mountains',ground:'raising the Misty Mountains',buildings:'',details:'planting Hollin',landmarks:'cutting the gates',el:'',traffic:'',ui:'lighting a lantern',halls:'delving the halls',city:'building the Mansions',walk:'finding the way',realm:'filling the halls',deep:'going under',events:'listening in the deep'}});
const ctx=window._iz={defaultCity:'moria',models:[landmarks],extras:[{name:'halls',fn:halls},{name:'city',fn:city},{name:'realm',fn:realm},{name:'deep',fn:deep},{name:'walk',fn:walk},{name:'events',fn:events}]};
boot(()=>build(ctx));
